    const errorCodes = [
      'SFB0000', 'SFB0001', 'SFB0002', 'SFB0003', 'SFB0004', 'SFB0005', 'SFB0006'
    ];

    component.form.setValue({
      name: 'name',
      email: 'email@gmail.com',
      password: 'password'
